package android.content;
import android.net.Uri;import android.database.Cursor;import android.os.ParcelFileDescriptor;import java.io.*;import java.util.*;
public abstract class ContentResolver { public abstract InputStream openInputStream(Uri uri)throws IOException; public OutputStream openOutputStream(Uri uri,String mode)throws IOException{throw new UnsupportedOperationException("output provider");} public abstract ParcelFileDescriptor openFileDescriptor(Uri uri,String mode)throws IOException; public abstract Cursor query(Uri uri,String[] fields,String a,String[] b,String c); public List<UriPermission> getPersistedUriPermissions(){return Collections.emptyList();} public Uri createDocument(Uri parent,String mime,String name)throws IOException{throw new UnsupportedOperationException("create provider");} public boolean deleteDocument(Uri uri)throws IOException{throw new UnsupportedOperationException("delete provider");} }
